cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const ws = wb.Sheets['Orders'];
const data = XLSX.utils.sheet_to_json(ws);

// Summary stats
const totalOrders = data.length;
const confirmed = data.filter(r => r['Status'] === 'confirmed').length;
const cancelled = data.filter(r => r['Status'] === 'cancelled').length;
const totalRevenue = data.reduce((s, r) => s + r['Total Paid'], 0);
const confirmedRevenue = data.filter(r => r['Status'] === 'confirmed').reduce((s, r) => s + r['Total Paid'], 0);

// Customer breakdown
const customers = {};
data.forEach(r => {
  if (!customers[r['Customer']]) customers[r['Customer']] = {orders: 0, total: 0, confirmed: 0, cancelled: 0};
  customers[r['Customer']].orders++;
  customers[r['Customer']].total += r['Total Paid'];
  customers[r['Customer']][r['Status']]++;
});

// Date breakdown
const dates = {};
data.forEach(r => {
  if (!dates[r['Date']]) dates[r['Date']] = {orders: 0, total: 0};
  dates[r['Date']].orders++;
  dates[r['Date']].total += r['Total Paid'];
});

// Top products
const products = {};
data.forEach(r => {
  r['Items'].split(', ').forEach(item => {
    if (!products[item]) products[item] = 0;
    products[item]++;
  });
});

console.log('--- Overall ---');
console.log('Total Orders:', totalOrders);
console.log('Confirmed:', confirmed, '| Cancelled:', cancelled);
console.log('Total Paid (all):', totalRevenue);
console.log('Total Paid (confirmed only):', confirmedRevenue);
console.log('Avg Order Value:', (totalRevenue / totalOrders).toFixed(2));

console.log('\n--- By Customer ---');
Object.entries(customers).sort((a,b) => b[1].total - a[1].total).forEach(([c,v]) => {
  console.log(c, ':', v.orders, 'orders,', v.confirmed, 'confirmed,', v.cancelled, 'cancelled, total \$' + v.total);
});

console.log('\n--- By Date ---');
Object.entries(dates).forEach(([d,v]) => console.log(d, ':', v.orders, 'orders, \$' + v.total));

console.log('\n--- Product Frequency (top 10) ---');
Object.entries(products).sort((a,b) => b[1] - a[1]).forEach(([p,c]) => console.log(c, 'x', p));
"
